const body = $input.item.json.body || $input.item.json;
const now = new Date().toISOString();

// Kaynak belirleme
const referer = body.referer || body._referer || '';
let source = 'Direct';
if (referer.includes('google')) source = 'Google Organic';
else if (referer.includes('linkedin')) source = 'LinkedIn';
else if (referer.includes('instagram')) source = 'Instagram';
else if (referer.includes('t.co') || referer.includes('twitter')) source = 'Twitter/X';
else if (referer.includes('albanexa.com/rehber')) source = 'Rehber (Internal)';
else if (referer.includes('albanexa.com')) source = 'Internal';
else if (referer.length > 0) source = referer.split('/')[2] || 'Other';

// Öncelik skoru
let priority = 'Normal';
const budget = body.budget || '';
if (budget.includes('50k') || budget.includes('150k') || budget.includes('300k')) priority = 'Yüksek';
if (budget.includes('5k-15k')) priority = 'Düşük';

return [{
  json: {
    name: body.name || body.fullName || '',
    email: body.email || '',
    phone: body.phone || '',
    company: body.company || '',
    message: body.message || '',
    service: body.service || body.interest || '',
    budget: budget,
    source: source,
    priority: priority,
    page: body.page || referer,
    createdAt: now,
    status: 'Yeni'
  }
}];
